/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

class Scanner {
  constructor(input) {
    this.input = input
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
    this.errors = []
  }

  peek(offset = 0) {
    return this.input[this.pos + offset]
  }

  advance() {
    const char = this.input[this.pos]
    this.pos++
    if (char === '\n') {
      this.line++
      this.column = 1
    } else if (char === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }
    return char
  }

  skipWhitespace() {
    while (this.pos < this.input.length) {
      const char = this.peek()
      if (char === ' ' || char === '\t' || char === '\r' || char === '\n') {
        this.advance()
      } else {
        break
      }
    }
  }

  skipLineComment() {
    // Skip the //
    this.advance()
    this.advance()
    // Skip until newline or end
    while (this.pos < this.input.length && this.peek() !== '\n') {
      this.advance()
    }
  }

  skipBlockComment() {
    const startLine = this.line
    const startColumn = this.column

    // Skip the /*
    this.advance()
    this.advance()

    let depth = 1
    while (this.pos < this.input.length && depth > 0) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }

    if (depth > 0) {
      this.errors.push({ line: startLine, column: startColumn, message: 'unterminated block comment' })
    }
  }

  parseString() {
    const startLine = this.line
    const startColumn = this.column

    // Skip opening quote
    this.advance()

    let result = ''
    let escaped = false

    while (this.pos < this.input.length) {
      const char = this.peek()

      if (escaped) {
        if (char === 'n') {
          result += '\n'
          this.advance()
        } else if (char === 't') {
          result += '\t'
          this.advance()
        } else if (char === 'r') {
          result += '\r'
          this.advance()
        } else if (char === '\\') {
          result += '\\'
          this.advance()
        } else if (char === '"') {
          result += '"'
          this.advance()
        } else if (char === '0') {
          result += '\0'
          this.advance()
        } else if (char === 'x') {
          // \xHH - exactly two hex digits
          this.advance()
          let hex = ''
          for (let i = 0; i < 2; i++) {
            if (this.pos < this.input.length && isHexDigit(this.peek())) {
              hex += this.peek()
              this.advance()
            } else {
              this.errors.push({ line: this.line, column: this.column, message: `invalid escape \\x` })
              return null
            }
          }
          result += String.fromCharCode(parseInt(hex, 16))
        } else if (char === 'u') {
          // \u{H...} - at least one hex digit
          this.advance()
          if (this.peek() !== '{') {
            this.errors.push({ line: this.line, column: this.column - 1, message: `invalid escape \\u` })
            return null
          }
          this.advance()
          let hex = ''
          while (this.pos < this.input.length && this.peek() !== '}') {
            if (isHexDigit(this.peek())) {
              hex += this.peek()
              this.advance()
            } else {
              this.errors.push({ line: this.line, column: this.column, message: `invalid escape \\u{` })
              return null
            }
          }
          if (hex.length === 0) {
            this.errors.push({ line: this.line, column: this.column, message: `invalid escape \\u{` })
            return null
          }
          if (this.peek() !== '}') {
            this.errors.push({ line: this.line, column: this.column, message: `invalid escape \\u` })
            return null
          }
          const codePoint = parseInt(hex, 16)
          if (codePoint > 0x10FFFF) {
            this.errors.push({ line: this.line, column: this.column, message: `invalid escape \\u{${hex}}` })
            return null
          }
          this.advance()
          result += String.fromCodePoint(codePoint)
        } else {
          const backslashLine = this.line
          const backslashColumn = this.column - 1
          this.errors.push({ line: backslashLine, column: backslashColumn, message: `invalid escape \\${char}` })
          return null
        }
        escaped = false
      } else if (char === '\\') {
        escaped = true
        this.advance()
      } else if (char === '"') {
        this.advance()
        return result
      } else if (char === '\n') {
        this.errors.push({ line: this.line, column: this.column, message: 'newline in string' })
        return null
      } else {
        result += char
        this.advance()
      }
    }

    // Unterminated string
    this.errors.push({ line: startLine, column: startColumn, message: 'unterminated string' })
    return null
  }

  parseRawString() {
    const startLine = this.line
    const startColumn = this.column

    // Skip r"
    this.advance()
    this.advance()

    let result = ''
    while (this.pos < this.input.length) {
      const char = this.peek()
      if (char === '"') {
        this.advance()
        return result
      } else {
        result += char
        this.advance()
      }
    }

    // Unterminated raw string
    this.errors.push({ line: startLine, column: startColumn, message: 'unterminated string' })
    return null
  }

  parseNumber() {
    const startPos = this.pos
    const startColumn = this.column

    // Hex, binary, or octal prefix
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      this.advance()
      this.advance()
      if (!isHexDigit(this.peek())) {
        this.errors.push({ line: this.line, column: startColumn, message: `invalid number ${this.input.substring(startPos, this.pos + 1)}` })
        return null
      }
      while (this.pos < this.input.length && (isHexDigit(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!isHexDigit(this.peek(-1)) || !isHexDigit(this.peek(1))) {
            break
          }
        }
        this.advance()
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      this.advance()
      this.advance()
      if (this.peek() !== '0' && this.peek() !== '1') {
        this.errors.push({ line: this.line, column: startColumn, message: `invalid number ${this.input.substring(startPos, this.pos + 1)}` })
        return null
      }
      while (this.pos < this.input.length && (this.peek() === '0' || this.peek() === '1' || this.peek() === '_')) {
        if (this.peek() === '_') {
          if ((this.peek(-1) !== '0' && this.peek(-1) !== '1') || (this.peek(1) !== '0' && this.peek(1) !== '1')) {
            break
          }
        }
        this.advance()
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
      this.advance()
      this.advance()
      if (this.peek() < '0' || this.peek() > '7') {
        this.errors.push({ line: this.line, column: startColumn, message: `invalid number ${this.input.substring(startPos, this.pos + 1)}` })
        return null
      }
      while (this.pos < this.input.length && ((this.peek() >= '0' && this.peek() <= '7') || this.peek() === '_')) {
        if (this.peek() === '_') {
          const prev = this.peek(-1)
          const next = this.peek(1)
          if ((prev < '0' || prev > '7') || (next < '0' || next > '7')) {
            break
          }
        }
        this.advance()
      }
    } else {
      // Decimal
      while (this.pos < this.input.length && (isDigit(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!isDigit(this.peek(-1)) || !isDigit(this.peek(1))) {
            break
          }
        }
        this.advance()
      }

      // Optional decimal point
      if (this.peek() === '.' && isDigit(this.peek(1))) {
        this.advance()
        while (this.pos < this.input.length && (isDigit(this.peek()) || this.peek() === '_')) {
          if (this.peek() === '_') {
            if (!isDigit(this.peek(-1)) || !isDigit(this.peek(1))) {
              break
            }
          }
          this.advance()
        }
      }

      // Optional exponent
      if ((this.peek() === 'e' || this.peek() === 'E') && 
          (isDigit(this.peek(1)) || 
           ((this.peek(1) === '+' || this.peek(1) === '-') && isDigit(this.peek(2))))) {
        this.advance()
        if (this.peek() === '+' || this.peek() === '-') {
          this.advance()
        }
        while (this.pos < this.input.length && (isDigit(this.peek()) || this.peek() === '_')) {
          if (this.peek() === '_') {
            if (!isDigit(this.peek(-1)) || !isDigit(this.peek(1))) {
              break
            }
          }
          this.advance()
        }
      }
    }

    // Check for invalid trailing characters
    if (this.pos < this.input.length && 
        (isLetter(this.peek()) || isDigit(this.peek()) || this.peek() === '_')) {
      const endPos = this.pos
      this.advance()
      this.errors.push({ line: this.line, column: startColumn, message: `invalid number ${this.input.substring(startPos, endPos + 1)}` })
      return null
    }

    return this.input.substring(startPos, this.pos)
  }

  parseIdentifier() {
    const startPos = this.pos

    while (this.pos < this.input.length && (isLetter(this.peek()) || isDigit(this.peek()) || this.peek() === '_')) {
      this.advance()
    }

    return this.input.substring(startPos, this.pos)
  }

  scan() {
    while (this.pos < this.input.length) {
      this.skipWhitespace()

      if (this.pos >= this.input.length) break

      // Check for comments
      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }

      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        if (this.errors.length > 0) return
        continue
      }

      const line = this.line
      const column = this.column
      const char = this.peek()

      // String
      if (char === '"') {
        const value = this.parseString()
        if (this.errors.length > 0) return
        this.tokens.push({ line, column, kind: 'string', body: JSON.stringify(value) })
      }
      // Raw string
      else if (char === 'r' && this.peek(1) === '"') {
        const value = this.parseRawString()
        if (this.errors.length > 0) return
        // Escape backslashes in raw strings
        const escaped = value.replace(/\\/g, '\\\\')
        this.tokens.push({ line, column, kind: 'rawstring', body: JSON.stringify(escaped) })
      }
      // Number
      else if (isDigit(char)) {
        const text = this.parseNumber()
        if (this.errors.length > 0) return
        this.tokens.push({ line, column, kind: 'number', body: text })
      }
      // Identifier or keyword
      else if (isLetter(char) || char === '_') {
        const text = this.parseIdentifier()
        const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
        this.tokens.push({ line, column, kind, body: text })
      }
      // Punctuation
      else if (isPunct(char)) {
        const text = this.parsePunct()
        this.tokens.push({ line, column, kind: 'punct', body: text })
      }
      // Unexpected character
      else {
        this.errors.push({ line, column, message: `unexpected character ${char}` })
        return
      }
    }
  }

  parsePunct() {
    const twoCharPuncts = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']

    if (this.pos + 1 < this.input.length) {
      const twoChar = this.peek() + this.peek(1)
      if (twoCharPuncts.includes(twoChar)) {
        this.advance()
        this.advance()
        return twoChar
      }
    }

    const char = this.peek()
    this.advance()
    return char
  }
}

function isDigit(char) {
  return char >= '0' && char <= '9'
}

function isHexDigit(char) {
  return isDigit(char) || (char >= 'a' && char <= 'f') || (char >= 'A' && char <= 'F')
}

function isLetter(char) {
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z')
}

function isPunct(char) {
  const puncts = '+-*/%=<>!(){}[],;.'.split('')
  return puncts.includes(char)
}

function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  const input = readFileSync(0, 'utf8')

  // Scan
  const scanner = new Scanner(input)
  scanner.scan()

  // Check for errors
  if (scanner.errors.length > 0) {
    const err = scanner.errors[0]
    process.stderr.write(`error: ${err.line}:${err.column}: ${err.message}\n`)
    process.exit(2)
  }

  // Output
  if (mode === 'tokens') {
    for (const token of scanner.tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
    }
  } else {
    // stats mode
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0,
    }

    for (const token of scanner.tokens) {
      counts[token.kind]++
    }

    process.stdout.write(`ident ${counts.ident}\n`)
    process.stdout.write(`keyword ${counts.keyword}\n`)
    process.stdout.write(`number ${counts.number}\n`)
    process.stdout.write(`punct ${counts.punct}\n`)
    process.stdout.write(`rawstring ${counts.rawstring}\n`)
    process.stdout.write(`string ${counts.string}\n`)

    const total = scanner.tokens.length
    process.stdout.write(`total ${total}\n`)
  }
}

main()
